@startuml

class City {
  + name : string
  + inhabitants : int
}

class Attraction {
  + name : string
  + address : string
}

class GuidedTour {
  + duration : int
  + visitorCount : int
}

class Discount {
  + amount : float
}

class Person {
  + name : string
}

class Visitor extends Person {}

class Guide extends Person {}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "*" -- "1" Guide
GuidedTour "1" -- "*" Visitor
GuidedTour "0..*" -- "0..1" Discount : applied to
Visitor "1" -- "*" Discount : receives

@enduml

